          "question": "1. 对顾客的用语",
          "overview": "对待顾客一般要使用特别礼貌的表达方式（商业敬语）（中级第15课会话）。疑问词不用“どうですか”，而用“いかがですか”，显得更为礼貌（初级第11课）。而且，比起“〜ですか”来，“〜でしょうか”是一种客气的询问方式，不会有强加于人的感觉（初级第31课）。“好き（喜欢）”“持ってくる（拿来）”等也要变成“お気に召す”“お持ちする”等礼貌的表达方式。",
