          "question": "5. 多くなってきている",
          "overview": "这是“〜てくる”“〜ていく”可以和“〜ている”等一起构成“多くなる＋〜てくる＋〜ている”的形式。全部一起使用的情况并不多见，但是多种表达形式搭配使用时，其排列顺序基本上是固定的，顺序依次是：Ⅰ复合动词“し始める”“し続ける”等 → Ⅱ〜てくる，〜ていく → Ⅲ〜てしまう → Ⅳ“〜ている”“〜つつある”等。表中同一行的表达形式不能一起使用。",
          "answer": "",
