          "question": "11. こちらの青いほう",
          "overview": "本课中“赤いほう（红色的）”“青いほう（蓝色的）”分别指“青いボトル（蓝色的瓶子）”和“赤いボトル（红色的瓶子）”，只是没有重复使用“ボトル”这个词，而用了“ほう”。通过使用“〜ほう”分别更为具体地加以说明。在汉语中，这种场合也可以说成“蓝色的”“红色的”。“〜ほう”虽然与其用法相近，但是比较的意味更浓。与表示比较的“〜より〜（の）ほうが〜”不同（初级第12课），这种用法是有选择性地一个一个提及。\n\n另外，本课中“こちら”的意思和“これ”相同，但是在说明两种以上事物时，含有指示方向语感的“こちら”表示对比的意义更为明显（初级第3课）。",
