          "question": "13. お／ご〜いたす",
          "overview": "“お／ご〜いたす”与“お／ご〜する”（初级第48课）“お／ご”后面均使用动词“ます形”去掉“ます”的形式，二者都是表示自谦的表达方式。一般使用“お／ご〜します”的形式。“お／ご〜いたします”含有抬高动作对象和对听话人表示尊敬的两层意思。这时，因为贬低了作为主语的动作主体，所以一般用于自己或属于自己一方的人。使用三类动词时，用“ご／お＋三类动词的汉字部分＋いたします”的形式，如“ご案内いたします”“お電話いたします”。\n\n一般来说，“ご／お”的使用区别决定于是否是汉语词。一般在汉语词前面接“ご”，和语词前面接“お”。但也有些词，本来是汉语词却前接“お”，如“お電話いたします”（初级第48课）。",
