          "question": "19. ご不明の点",
          "overview": "“不明”是名词，表示不清楚的意思，后续“の”用于连接其后的名词。“不明”可以前接表示尊敬的“ご”，表示对方不清楚。“不明の点”指“不清楚的地方”，是比较郑重的表达方式。“ご不明の点がございましたら，〜”是“分からないところがあったら，〜（如有不清楚的地方，〜）”的礼貌表达方式。",
